\version "2.27.2"
% automatically converted by musicxml2ly from 45c-SimpleRepeat-Nested.xml
\pointAndClickOff

\header {
  texidoc = "Repeats can also be nested. The inner repeat spans from bar 2 to
    bar bar 3 (to be played five times). The outer repeat spans implicitly from
    the beginning to bar 7 (to be played one time, i.e., it doesn't get
    repeated)."
}
\layout {
  \context {
    \Staff
    printKeyCancellation = ##f
  }
  \context {
    \Score
    doubleRepeatBarType = ":|.|:"
    printTrivialVoltaRepeats = ##t
    autoBeaming = ##f
  }
}
PartPOneVoiceOne = \relative c' {
  \repeat volta 1 {
    \clef "treble" \time 4/4 \key c \major R1 | % 1
    \repeat volta 5 {
      R1 | % 2
      R1 | % 3
    }
    R1 | % 4
    R1 | % 5
    R1 | % 6
    R1 | % 7
  }
  R1 \bar "|."
}


% The score definition
\score {
  <<
    \new Staff = "P1" <<
      \context Staff <<
        \override Staff.BarLine.allow-span-bar = ##f
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPOneVoiceOne" {
          \PartPOneVoiceOne
        }
      >>
    >>
  >>
  \layout {}
